content:
 MySQL 最常用 Top 30 函数（含例子）

1. IFNULL(expr, alt) — NULL 替代（最常用之一）SELECT IFNULL(nickname, &#x27;未填写&#x27;) AS nick FROM user;

2. COALESCE(a, b, c...) — 多字段取第一个非 NULLSELECT COALESCE(phone, email, &#x27;无联系方式&#x27;) FROM user;

3. NULLIF(a, b) — a&#x3D;b 则 NULLSELECT NULLIF(status, &#x27;未知&#x27;);

4. IF(expr, true_val, false_val) — 条件判断SELECT IF(score&gt;=60,&#x27;及格&#x27;,&#x27;不及格&#x27;) FROM exam;

5. CASE WHEN — 多分支判断（业务最常用）SELECT CASE WHEN age&lt;18 THEN &#x27;未成年&#x27; WHEN age&lt;60 THEN &#x27;成年人&#x27; ELSE &#x27;老年人&#x27; END;


6. CONCAT(a,b) — 字符串拼接SELECT CONCAT(first_name,&#x27; &#x27;,last_name) FROM user;

7. CONCAT_WS(sep,a,b) — 忽略 NULL 的拼接SELECT CONCAT_WS(&#x27;-&#x27;, country, province, city) FROM address;

8. REPLACE(str, from, to) — 替换SELECT REPLACE(&#x27;a-b-c&#x27;,&#x27;-&#x27;,&#x27;_&#x27;);

9. LEFT(str,n) &#x2F; RIGHT(str,n) — 左右截SELECT LEFT(&#x27;abcdef&#x27;,3); -- abc

10. SUBSTRING(str, pos, len) — 中间截SELECT SUBSTRING(&#x27;abcdef&#x27;,2,3); -- bcd

11. INSTR(str, substr) — 判断是否包含（比 LIKE 快）SELECT INSTR(&#x27;hello&#x27;,&#x27;ll&#x27;); -- 3  (&gt;0 表示存在)

12. LENGTH(str) &#x2F; CHAR_LENGTH(str)SELECT LENGTH(&#x27;中文&#x27;), CHAR_LENGTH(&#x27;中文&#x27;); -- 6,2


13. TRIM() — 去空格SELECT TRIM(&#x27;  abc  &#x27;);

14. LPAD() &#x2F; RPAD() — 左右补齐SELECT LPAD(&#x27;5&#x27;, 3, &#x27;0&#x27;); -- 005


15. NOW() — 当前时间SELECT NOW();

16. CURDATE() &#x2F; CURTIME()SELECT CURDATE(), CURTIME();

17. DATE_FORMAT(date, fmt) — 返回格式化日期（销量统计必用）SELECT DATE_FORMAT(NOW(),&#x27;%Y-%m&#x27;); -- 2025-11

18. STR_TO_DATE(str, fmt) — 字符串转日期SELECT STR_TO_DATE(&#x27;2025-11-19&#x27;,&#x27;%Y-%m-%d&#x27;);

19. DATE_ADD() &#x2F; DATE_SUB() — 加天、加年等日期运算SELECT DATE_ADD(&#x27;2025-01-01&#x27;, INTERVAL 7 DAY);

20. DATEDIFF(a,b) — 天数差SELECT DATEDIFF(&#x27;2025-01-10&#x27;,&#x27;2025-01-01&#x27;); -- 9

21. TIMESTAMPDIFF(unit,a,b) — 年&#x2F;月&#x2F;日差值（业务必用）SELECT TIMESTAMPDIFF(MONTH,&#x27;2024-01-01&#x27;,&#x27;2025-01-01&#x27;); -- 12


22. COUNT(*) — 计数（最常用聚合）SELECT COUNT(*) FROM orders;

23. SUM() &#x2F; AVG() &#x2F; MIN() &#x2F; MAX()SELECT SUM(amount), AVG(amount) FROM orders;

24. GROUP_CONCAT() — 分组拼接列表SELECT user_id, GROUP_CONCAT(tag) FROM user_tag GROUP BY user_id;


25. ROUND(x,d) — 四舍五入SELECT ROUND(3.14159,2);

26. FLOOR() &#x2F; CEIL() — 向下&#x2F;向上取整SELECT CEIL(5.1), FLOOR(5.9); -- 6,5

27. MOD(a,b) — 取余SELECT MOD(10,3); -- 1

28. RAND() — 随机数SELECT RAND();


29. JSON_EXTRACT() &#x2F; -&gt; — JSON 取值SELECT info-&gt;&#x27;$.address.city&#x27; FROM user;

30. CAST(expr AS type) — 类型转换SELECT CAST(&#x27;123&#x27; AS SIGNED);


✔ 额外：窗口函数（8.0+ 最常用的 3 个）
真正在业务里最常写的只有三个：

① ROW_NUMBER() — 排名（不重复）ROW_NUMBER() OVER(PARTITION BY dept ORDER BY score DESC)

② RANK() — 并列排名RANK() OVER(ORDER BY salary DESC)

③ LAG() — 上一行值（做环比最常用）LAG(amount, 1) OVER(ORDER BY month)

一、空值与条件处理（NULL &#x2F; 条件）IF(expr, true_val, false_val) — 三元判断SELECT IF(score &gt;= 60, &#x27;及格&#x27;, &#x27;不及格&#x27;) FROM exam;

IFNULL(expr, alt) — expr 为 NULL 则用 altSELECT IFNULL(nickname, &#x27;未填写&#x27;) FROM user;

COALESCE(expr1, expr2, ...) — 返回第一个非 NULL 值SELECT COALESCE(NULL, &#x27;&#x27;, &#x27;a&#x27;);  -- 返回 &#x27;&#x27;

NULLIF(a, b) — 若 a &#x3D; b 返回 NULL，否则返回 aSELECT NULLIF(&#x27;&#x27;, &#x27;&#x27;);  -- 返回 NULL

CASE ... WHEN ... THEN ... END — 多分支条件SELECT CASE WHEN score&gt;=90 THEN &#x27;A&#x27; WHEN score&gt;=60 THEN &#x27;B&#x27; ELSE &#x27;C&#x27; END FROM exam;

二、字符串函数（String）CONCAT(a,b,...) — 拼接SELECT CONCAT(first_name, &#x27; &#x27;, last_name) FROM user;

CONCAT_WS(sep, a, b, ...) — 带分隔符拼接（跳过 NULL）SELECT CONCAT_WS(&#x27;-&#x27;, country, province, city) FROM addr;

SUBSTRING(str, pos, len) &#x2F; SUBSTR — 截取SELECT SUBSTRING(&#x27;abcdef&#x27;, 2, 3); -- bcd

LEFT(str, n) &#x2F; RIGHT(str, n) — 左&#x2F;右取 n 字符SELECT LEFT(&#x27;abcdef&#x27;, 2); -- ab

LENGTH(str) — 字节长度；CHAR_LENGTH(str) — 字符长度SELECT LENGTH(&#x27;中文&#x27;), CHAR_LENGTH(&#x27;中文&#x27;); -- 6,2（视字符集）

INSTR(str, substr) &#x2F; LOCATE(substr, str) — 查子串位置（&gt;0 表示存在）SELECT INSTR(&#x27;hello&#x27;, &#x27;ll&#x27;); -- 3

REPLACE(str, from, to) — 替换子串SELECT REPLACE(&#x27;a-b-c&#x27;,&#x27;-&#x27;,&#x27;_&#x27;); -- a_b_c

TRIM(str) &#x2F; LTRIM &#x2F; RTRIM — 去空白SELECT TRIM(&#x27;  abc  &#x27;);

LPAD(str, len, pad) &#x2F; RPAD — 左右补齐SELECT LPAD(&#x27;5&#x27;, 3, &#x27;0&#x27;); -- &#x27;005&#x27;

LOWER(str) &#x2F; UPPER(str) — 大小写转换SELECT UPPER(&#x27;abc&#x27;); -- &#x27;ABC&#x27;

FORMAT(number, d) — 格式化数字（千分位、指定位小数）SELECT FORMAT(12345.678, 2); -- &#x27;12,345.68&#x27;

FIND_IN_SET(str, strlist) — 在逗号分隔列表中查找（常用于 set-like）SELECT FIND_IN_SET(&#x27;b&#x27;, &#x27;a,b,c&#x27;); -- 2

FIELD(val, val1, val2, ...) — 自定义顺序排序&#x2F;匹配索引（返回位置）SELECT FIELD(&#x27;处理中&#x27;,&#x27;待支付&#x27;,&#x27;处理中&#x27;,&#x27;已完成&#x27;); -- 2

REGEXP &#x2F; RLIKE — 正则匹配（不是函数但常用）SELECT * FROM user WHERE email REGEXP &#x27;^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]&#123;2,&#125;$&#x27;;

三、数值函数（Numeric）ABS(x) — 绝对值SELECT ABS(-5); -- 5

ROUND(x, d) &#x2F; TRUNCATE(x, d) — 四舍五入 &#x2F; 截断SELECT ROUND(3.14159, 2), TRUNCATE(3.14159, 2); -- 3.14, 3.14

CEIL(x) &#x2F; FLOOR(x) — 向上&#x2F;向下取整SELECT CEIL(2.1), FLOOR(2.9); -- 3,2

MOD(a, b) — 取模（余数）SELECT MOD(10,3); -- 1

POWER(x, y) — 幂SELECT POWER(2,3); -- 8

RAND() — 随机数（0~1）SELECT RAND();

四、日期时间函数（Date &amp; Time）NOW() &#x2F; CURRENT_TIMESTAMP() — 当前时间SELECT NOW();

CURDATE() &#x2F; CURTIME() — 当前日期 &#x2F; 时间SELECT CURDATE(), CURTIME();

DATE(expr) — 取日期部分（去掉时分秒）SELECT DATE(&#x27;2025-11-19 12:34:56&#x27;); -- &#x27;2025-11-19&#x27;

DATE_FORMAT(date, fmt) — 按格式输出SELECT DATE_FORMAT(NOW(), &#x27;%Y-%m&#x27;); -- &#x27;2025-11&#x27;

STR_TO_DATE(str, fmt) — 字符串转日期SELECT STR_TO_DATE(&#x27;2025-11-19&#x27;,&#x27;%Y-%m-%d&#x27;);

DATE_ADD(date, INTERVAL n unit) &#x2F; DATE_SUB — 日期加减SELECT DATE_ADD(&#x27;2025-01-01&#x27;, INTERVAL 7 DAY); -- &#x27;2025-01-08&#x27;

DATEDIFF(a, b) — 天数差（a - b）SELECT DATEDIFF(&#x27;2025-01-10&#x27;,&#x27;2025-01-01&#x27;); -- 9

TIMESTAMPDIFF(unit, a, b) — 指定单位差值（YEAR, MONTH, DAY, HOUR…）SELECT TIMESTAMPDIFF(MINUTE, &#x27;2025-01-01 00:00:00&#x27;, &#x27;2025-01-01 01:30:00&#x27;); -- 90

UNIX_TIMESTAMP() &#x2F; FROM_UNIXTIME() — 时间戳互转SELECT UNIX_TIMESTAMP(NOW()), FROM_UNIXTIME(UNIX_TIMESTAMP());

五、聚合函数（Aggregate）COUNT(*) &#x2F; COUNT(col) — 计数SELECT COUNT(*) FROM orders;

SUM(col) &#x2F; AVG(col) &#x2F; MIN &#x2F; MAX — 求和&#x2F;平均&#x2F;最小&#x2F;最大SELECT SUM(amount), AVG(amount), MIN(amount), MAX(amount) FROM orders;

GROUP_CONCAT(expr [ORDER BY ... SEPARATOR &#39;,&#39;]) — 分组拼接SELECT user_id, GROUP_CONCAT(product_name ORDER BY product_name SEPARATOR &#x27;;&#x27;) FROM orders GROUP BY user_id;

六、JSON（MySQL 5.7+）JSON_EXTRACT(json, path) 或 col-&gt;&#39;$.a.b&#39; — 取值SELECT JSON_EXTRACT(info, &#x27;$.address.city&#x27;) FROM user;SELECT info-&gt;&#x27;$.address.city&#x27; FROM user;

JSON_SET(json, path, val) &#x2F; JSON_REPLACE &#x2F; JSON_INSERT — 修改或插入UPDATE user SET info = JSON_SET(info, &#x27;$.age&#x27;, 30) WHERE id = 1;

JSON_CONTAINS(json, val [, path]) — 判断包含关系SELECT * FROM product WHERE JSON_CONTAINS(tags, &#x27;&quot;热门&quot;&#x27;);

JSON_ARRAY() &#x2F; JSON_OBJECT() &#x2F; JSON_LENGTH() — 构造与长度SELECT JSON_ARRAY(&#x27;a&#x27;,&#x27;b&#x27;), JSON_OBJECT(&#x27;k&#x27;,&#x27;v&#x27;), JSON_LENGTH(&#x27;[1,2,3]&#x27;);

七、类型转换（CAST &#x2F; CONVERT）CAST(expr AS type) &#x2F; CONVERT(expr, type) — 强制类型转换SELECT CAST(&#x27;123&#x27; AS SIGNED), CAST(123.45 AS CHAR);

八、加密 &#x2F; 编码 &#x2F; UUIDMD5(str) &#x2F; SHA1(str) — 单向哈希SELECT MD5(&#x27;password&#x27;);

HEX(str) &#x2F; UNHEX(str) — 十六进制编码&#x2F;解码SELECT HEX(&#x27;abc&#x27;), UNHEX(&#x27;616263&#x27;);

UUID() &#x2F; UUID_SHORT() — 唯一 IDSELECT UUID(), UUID_SHORT();

九、窗口函数（MySQL 8.0+）
常用模式：OVER(PARTITION BY ... ORDER BY ...)

ROW_NUMBER() — 行号SELECT id, user_id, amount, ROW_NUMBER() OVER(PARTITION BY user_id ORDER BY amount DESC) rn FROM orders;

RANK() &#x2F; DENSE_RANK() — 排名（并列）SELECT score, RANK() OVER(ORDER BY score DESC) FROM student;

SUM(...) OVER(...) &#x2F; AVG(...) OVER(...) — 滚动&#x2F;累计SELECT id, amount, SUM(amount) OVER(ORDER BY id) AS running_total FROM orders;

LAG(col, offset, default) &#x2F; LEAD(...) — 前&#x2F;后行值SELECT id, amount, LAG(amount) OVER(ORDER BY id) prev_amt FROM orders;

十、实用组合示例（综合）示例 1：查询用户当月消费 + 上月消费 + 同比环比SELECT  user_id,  DATE_FORMAT(pay_time, &#x27;%Y-%m&#x27;) AS month,  SUM(amount) AS month_total,  LAG(SUM(amount)) OVER (PARTITION BY user_id ORDER BY DATE_FORMAT(pay_time, &#x27;%Y-%m&#x27;)) AS prev_month_totalFROM ordersGROUP BY user_id, DATE_FORMAT(pay_time, &#x27;%Y-%m&#x27;);

示例 2：将 NULL 或 空串统一成默认值SELECT COALESCE(NULLIF(nickname, &#x27;&#x27;), &#x27;未填写&#x27;) AS nick FROM user;

示例 3：带窗口的分组 TopN（每组前 3）SELECT * FROM (  SELECT id, dept, score,    ROW_NUMBER() OVER(PARTITION BY dept ORDER BY score DESC) AS rn  FROM employee) t WHERE rn &lt;= 3;

learn english ways-1

Every morning, when you open your eyes, first think about what you need to do next in English;
When you hear English songs or podcasts, visualize the scenes described in your mind;
Do not connect English with reality through your mother tongue, but directly connect English with reality;
At the beginning, do not pay too much attention to grammar and speed, and be brave in trying, as it is more important than a perfect result, but also be careful to avoid some mistakes;
Every week, review the past seven days in your mind in English;
Definitely practice more, continuously improve your proficiency, and avoid mistakes.

